type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // Extract R and C as usize for indexing
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    let len = a.len();

    // Prepare the output matrix
    let mut matrix = Vec::with_capacity(r);

    if len == r {
        // Column vector broadcasting
        // For each row i, fill the row with a[i] repeated c times
        for i in 0..r {
            let row_val = a[i];
            let row_vec = vec![row_val; c];
            matrix.push(row_vec);
        }
    } else {
        // Row vector broadcasting (len == c)
        // For each row i, clone the entire row array a
        for _ in 0..r {
            matrix.push(a.clone());
        }
    }

    matrix
}